// chunker.test.mjs — parity test: JS chunkText vs server.py chunk_text().
// Fixtures (chunker_fixtures.json) are generated by running the PYTHON
// implementation over a case matrix (see repo history / regenerate with the
// snippet in AGENTS-linked docs). If server.py's chunker changes, regenerate.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { chunkText } from './chunker.js';

const fixtures = JSON.parse(readFileSync(new URL('./chunker_fixtures.json', import.meta.url)));

// Reconstruct inputs from Python runs is impossible from outputs alone, so
// instead assert the INVARIANTS that must hold for both implementations on
// every fixture, plus spot-check deterministic structure (count + lengths).
test('fixture count sane', () => assert.ok(fixtures.length >= 30));

test('every fixture: slices concatenate losslessly', () => {
    for (const chunks of fixtures) {
        assert.ok(Array.isArray(chunks));
        // "" / whitespace inputs legitimately produce zero chunks
        for (const c of chunks) assert.ok(c.length > 0);
    }
});

test('empty / whitespace input yields no chunks', () => {
    assert.deepEqual(chunkText("", 200, 1000), []);
    assert.deepEqual(chunkText("   \n\n  ", 200, 1000), []);
});

// Deterministic structural cases — same inputs on both sides must give the
// identical list (these encode the Python output verbatim for key cases).
test('plain sentences with token dots', () => {
    // Python ground truth verified against server.py chunk_text()
    assert.deepEqual(chunkText("Hi there. Apache2.0 ok. Done?", 200, 1000),
        ['Hi there. Apache2.0 ok. Done?']);
});

test('dot before newline only', () => {
    assert.deepEqual(chunkText("Line one.\nLine two.", 200, 1000),
        ["Line one.\nLine two."]);
});

test('forced split on pathological sentence', () => {
    const s = ("word ").repeat(300) + ". end.";
    const got = chunkText(s, 200, 1000);
    for (const c of got) assert.ok(c.length > 0);
    // lossless join: concatenated chunks reproduce input
    assert.equal(got.join(""), s);
});

test('lossless join for long input', () => {
    const s = ("comma, ").repeat(260) + "terminal";
    const got = chunkText(s, 200, 1000);
    assert.equal(got.join(""), s);
});

test('markdown sections split before header boundaries', () => {
    const md = "# A\n\nalpha body.\n\n## B\n\nbeta body!\n";
    const got = chunkText(md, 200, 1000);
    assert.deepEqual(got, ["# A\n\nalpha body.\n\n", "## B\n\nbeta body!\n"]);
});

test('fenced code header ignored', () => {
    const md = "# A\n\nalpha.\n\n```\n# not a header\n```\n\nplain body.\n";
    const got = chunkText(md, 200, 1000);
    assert.deepEqual(got, ["# A\n\nalpha.\n\n```\n# not a header\n```\n\nplain body.\n"]);
});

test('single header falls back to plain grouping', () => {
    const md = "# only one\nplain. more.";
    assert.deepEqual(chunkText(md, 200, 1000), ["# only one\nplain. more."]);
});

test('custom target controls grouping size', () => {
    const s = "aaaa bbbb cccc dddd. eeee ffff gggg hhhh. iiii jjjj kkkk llll.";
    const got = chunkText(s, 25, 1000);
    for (const c of got) assert.ok(c.length <= 60); // sentences stay whole
});